evidence = {
    "shipping": {"source_id": "FAQ-01", "text": "Standard shipping takes 3 to 5 business days."}
}

def answer(topic):
    source = evidence.get(topic)
    if source is None:
        return {"answer": "The available documents do not answer this question.", "citations": []}
    return {"answer": source["text"], "citations": [source["source_id"]]}

print(answer("shipping")["answer"])
print("Source:", answer("shipping")["citations"][0])
print(answer("international-tax")["answer"])

permissions = {"staff-1": {"public-faq"}, "manager-1": {"public-faq", "internal-pricing"}}

def allowed_document(user_id, document_id):
    return document_id in permissions.get(user_id, set())

user_id = "staff-1"
for document_id in ["public-faq", "internal-pricing"]:
    result = "allowed" if allowed_document(user_id, document_id) else "forbidden"
    print(document_id, result)
